type Screen='home'|'chats'|'create'|'reels'|'profile'|'discover'|'wallet'|'notifications'|'ai'|'live'|'games'|'settings';
const reels=[{title:'ZENO Night',user:'@maya',views:'12.4K',tag:'TRENDING',emoji:'🌃'},{title:'Behind the Scene',user:'@omar',views:'8.9K',tag:'NEW',emoji:'🎬'},{title:'AI Magic',user:'@lina',views:'21K',tag:'AI',emoji:'✦'}];

function Logo(){return <View style={st.logoWrap}><Text style={st.logo}>ZENO</Text><Text style={st.tag}>MORE THAN JUST CHAT.</Text></View>}
function Home({go}:{go:(s:Screen)=>void}){
  const pulse=React.useRef(new Animated.Value(0)).current;
  React.useEffect(()=>{const loop=Animated.loop(Animated.sequence([
    Animated.timing(pulse,{toValue:1,duration:2200,easing:Easing.inOut(Easing.ease),useNativeDriver:true}),
    Animated.timing(pulse,{toValue:0,duration:2200,easing:Easing.inOut(Easing.ease),useNativeDriver:true})
  ]));loop.start();return()=>loop.stop()},[pulse]);
  const glowScale=pulse.interpolate({inputRange:[0,1],outputRange:[.92,1.08]});
  const glowOpacity=pulse.interpolate({inputRange:[0,1],outputRange:[.22,.48]});
  return <ScrollView contentContainerStyle={st.page} showsVerticalScrollIndicator={false}>
    <View style={st.homeTop}>
      <View style={st.homeIdentity}>
        <View style={st.miniBrand}><Text style={st.miniBrandText}>Z</Text></View>
        <View><Text style={st.muted}>مساء النور 👋</Text><Text style={st.homeTitle}>جاهز تدخل عالم ZENO؟</Text></View>
      </View>
      <IconButton icon="⌁" badge onPress={()=>go('notifications')}/>
    </View>

    <LinearGradient colors={['#111C45','#24124B','#0C1023']} start={{x:0,y:0}} end={{x:1,y:1}} style={st.cinematicHero}>
      <Animated.View pointerEvents="none" style={[st.heroGlow,{transform:[{scale:glowScale}],opacity:glowOpacity}]}/>
      <View style={st.heroGridLine}/><View style={[st.heroGridLine,{top:118,left:32,right:32,transform:[{rotate:'-8deg'}]}]}/>
      <View style={st.heroHeader}>
        <Pill active><Text style={st.pillText}>✦ ZENO EXPERIENCE</Text></Pill>
        <View style={st.liveSignal}><View style={st.liveDot}/><Text style={st.heroLive}>LIVE NOW</Text></View>
      </View>
      <View style={st.heroOrbRow}>
        <View style={st.heroCopy}>
          <Text style={st.heroEyebrow}>MORE THAN JUST CHAT.</Text>
          <Text style={st.heroTitleBig}>اتكلم.{`\n`}اعمل.{`\n`}اتفرج.</Text>
          <Text style={st.heroSub}>كل لحظة ليها مكان. وكل شخص ليه عالم.</Text>
        </View>
        <Animated.View style={[st.heroOrb,{transform:[{scale:glowScale}]}]}>
          <LinearGradient colors={['#4D7CFF','#8B5CF6','#22D3EE']} style={st.heroOrbInner}>
            <Text style={st.heroOrbZ}>Z</Text><Text style={st.heroOrbCaption}>ZENOVERSE</Text>
          </LinearGradient>
        </Animated.View>
      </View>
      <View style={st.heroActions}>
        <GradientButton title="ابدأ الاستكشاف  ›" onPress={()=>go('discover')} small/>
        <Pressable onPress={()=>go('live')} style={st.heroGhost}><Text style={st.heroGhostText}>شوف Live</Text></Pressable>
      </View>
    </LinearGradient>

    <View style={st.signalRow}>
      {[['12.8K','ناس أونلاين'],['248','Live الآن'],['∞','لحظاتك']].map(([n,l])=><View key={l} style={st.signalItem}><Text style={st.signalNumber}>{n}</Text><Text style={st.signalLabel}>{l}</Text></View>)}
    </View>

    <SectionTitle title="دلوقتي على ZENO" action="عرض الكل" onAction={()=>go('live')}/>
    <ScrollView horizontal showsHorizontalScrollIndicator={false} style={st.hScroll} contentContainerStyle={st.liveRail}>
      {['Maya','Omar','Lina','Kareem','Nour'].map((x,i)=><Pressable key={x} onPress={()=>go('live')} style={st.liveSpotlight}>
        <LinearGradient colors={i%2?['#263C9B','#8B5CF6']:['#8B5CF6','#22D3EE']} style={st.liveHalo}><View style={st.liveAvatarShell}><Avatar label={x} size={54} online/></View></LinearGradient>
        <Text style={st.name}>{x}</Text><Text style={st.liveText}>● LIVE · {12+i*7}K</Text>
      </Pressable>)}
    </ScrollView>

    <SectionTitle title="اختار مودك" action=""/>
    <View style={st.modeGrid}>
      {[['✦','ZENO AI','فكرة؟ خليها تبدأ هنا','ai'],['🎮','GAMES','نافس · اجمع XP','games'],['◉','REELS','شوف حاجة جديدة','reels'],['💎','WALLET','Coins · Gifts','wallet']].map((x,i)=><GlassCard key={x[1]} onPress={()=>go(x[3] as Screen)} style={[st.modeCard,i===0&&st.modeCardFeatured]}><View style={st.modeIcon}><Text style={st.modeIconText}>{x[0]}</Text></View><Text style={st.modeTitle}>{x[1]}</Text><Text style={st.modeSub}>{x[2]}</Text><Text style={st.modeArrow}>↗</Text></GlassCard>)}
    </View>

    <LinearGradient colors={['#18112D','#10172F']} style={st.luckBanner}>
      <View style={st.luckBadge}><Text style={st.luckBadgeText}>SURPRISE</Text></View>
      <Text style={st.luckTitle}>🎉 حدث مفاجئ بدأ الآن</Text>
      <Text style={st.luckSub}>سؤال واحد… ممكن يغيّر مكافأتك.</Text>
      <Pressable onPress={()=>go('games')}><Text style={st.luckAction}>ادخل التحدي  ›</Text></Pressable>
    </LinearGradient>

    <SectionTitle title="Reels المختارة ليك" action="شوف الكل" onAction={()=>go('reels')}/>
    <ScrollView horizontal showsHorizontalScrollIndicator={false}>{reels.map((r,i)=><Pressable key={r.title} onPress={()=>go('reels')} style={st.reelMini}><LinearGradient colors={i===0?['#0D2047','#4C1D95']:i===1?['#25113D','#0B3551']:['#101B3C','#3D1E68']} style={st.reelArt}><Text style={st.reelEmoji}>{r.emoji}</Text><View style={st.reelBottom}><Pill active><Text style={st.tiny}>{r.tag}</Text></Pill><Text style={st.reelName}>{r.title}</Text><Text style={st.reelMeta}>{r.user} · {r.views} مشاهدة</Text></View></LinearGradient></Pressable>)}</ScrollView>

    <GlassCard onPress={()=>go('create')} style={st.creatorPremium}><LinearGradient colors={['#4D7CFF','#A855F7']} style={st.creatorOrbPremium}><Text style={st.creatorOrbText}>＋</Text></LinearGradient><View style={{flex:1}}><Text style={st.quickTitle}>اصنع لحظتك</Text><Text style={st.quickSub}>Post · Reel · Live · AI Content</Text></View><Text style={st.arrow}>›</Text></GlassCard>
  </ScrollView>
}
function Chats({go,onStartCall}:{go:(s:Screen)=>void;onStartCall:(call:ActiveCall)=>void}){
  const [items,setItems]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [selected,setSelected]=useState<any|null>(null); const [other,setOther]=useState<any|null>(null); const stopRef=React.useRef<null|(()=>void)>(null);
  const [messages,setMessages]=useState<any[]>([]); const [draft,setDraft]=useState('');
  const load=async()=>{setLoading(true);const {data:{user}}=await supabase.auth.getUser();if(!user){setLoading(false);return}
    const {data:members}=await supabase.from('conversation_members').select('conversation_id,last_read_at').eq('user_id',user.id);
    const ids=(members||[]).map((m:any)=>m.conversation_id); if(!ids.length){setItems([]);setLoading(false);return}
    const {data:convs}=await supabase.from('conversations').select('id,kind,last_message_at,last_message_id').in('id',ids).order('last_message_at',{ascending:false,nullsFirst:false});
    const rows:any[]=[]; for(const c of convs||[]){const {data:ms}=await supabase.from('conversation_members').select('user_id,last_read_at').eq('conversation_id',c.id).neq('user_id',user.id);const member=ms?.[0];let profile:any=null;if(member){const r=await supabase.from('profiles').select('id,username,display_name,avatar_url,is_verified').eq('id',member.user_id).maybeSingle();profile=r.data}
      let last:any=null;if(c.last_message_id){const r=await supabase.from('messages').select('body,created_at,sender_id').eq('id',c.last_message_id).maybeSingle();last=r.data}
      const unread=await supabase.rpc('get_unread_count',{p_conversation_id:c.id}); rows.push({...c,otherId:member?.user_id,profile,last,unread:unread.data||0});}
    setItems(rows);setLoading(false);
  };
  useEffect(()=>{load();},[]);
  const open=async(item:any)=>{setSelected(item);setOther(item.profile);await zeno.chat.markRead(item.id);const {data}=await supabase.from('messages').select('id,conversation_id,sender_id,body,message_type,created_at,edited_at,deleted_at').eq('conversation_id',item.id).order('created_at',{ascending:true}).limit(200);setMessages(data||[]);const stop=subscribeToConversation(item.id,(payload)=>{if(payload.eventType==='INSERT')setMessages(v=>v.some(x=>x.id===payload.new.id)?v:[...v,payload.new]);if(payload.eventType==='UPDATE')setMessages(v=>v.map(x=>x.id===payload.new.id?payload.new:x));if(payload.eventType==='DELETE')setMessages(v=>v.filter(x=>x.id!==payload.old.id));});stopRef.current=stop;};
  useEffect(()=>()=>{stopRef.current?.()},[]);
  const send=async()=>{const body=draft.trim();if(!body||!selected)return;setDraft('');const {data,error}=await zeno.chat.send(selected.id,body);if(error){setDraft(body);Alert.alert('تعذر الإرسال',error.message);}}
  if(selected)return <KeyboardAvoidingView style={st.flex} behavior={Platform.OS==='ios'?'padding':undefined}><View style={st.header}><View style={u.row}><IconButton icon="‹" onPress={()=>{stopRef.current?.();stopRef.current=null;setSelected(null);load()}}/><Avatar label={other?.display_name||other?.username||'User'} size={46} online/></View><View style={{flex:1,marginLeft:10}}><Text style={st.h1}>{other?.display_name||other?.username||'محادثة'}</Text><Text style={st.muted}>@{other?.username||'zeno'} · ZENO</Text></View><View style={u.row}><IconButton icon="📞" onPress={async()=>{if(!selected?.otherId)return;const r=await zeno.calls.create(selected.otherId,'voice',selected.id);if(r.error){Alert.alert('المكالمة',r.error.message);return}onStartCall({callId:r.data,otherId:selected.otherId,otherName:other?.display_name||other?.username||'ZENO User',type:'voice',isCaller:true});}}/><IconButton icon="📹" onPress={async()=>{if(!selected?.otherId)return;const r=await zeno.calls.create(selected.otherId,'video',selected.id);if(r.error){Alert.alert('المكالمة',r.error.message);return}onStartCall({callId:r.data,otherId:selected.otherId,otherName:other?.display_name||other?.username||'ZENO User',type:'video',isCaller:true});}}/></View></View><ScrollView contentContainerStyle={st.page}>{messages.map((m:any)=><View key={m.id} style={[st.aiMsg,m.sender_id===selected.otherId?st.aiBot:st.aiUser]}><Text style={st.aiText}>{m.deleted_at?'تم حذف الرسالة':m.body||''}</Text><Text style={st.time}>{new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</Text></View>)}</ScrollView><View style={st.composer}><TextInput value={draft} onChangeText={setDraft} placeholder="اكتب رسالة..." placeholderTextColor={ZENO.colors.muted} style={st.input} onSubmitEditing={send}/><Pressable onPress={send} style={st.send}><Text style={{color:'#fff',fontSize:19}}>➤</Text></Pressable></View></KeyboardAvoidingView>;
  return <View style={st.flex}><View style={st.header}><View><Text style={st.h1}>Chats</Text><Text style={st.muted}>محادثاتك الحقيقية على ZENO</Text></View><IconButton icon="＋" onPress={()=>go('discover')}/></View><View style={st.search}><Text style={st.searchIcon}>⌕</Text><TextInput placeholder="ابحث في المحادثات" placeholderTextColor={ZENO.colors.muted} style={st.searchInput}/></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={st.filters}>{['الكل','غير مقروء','Online','طلبات'].map((x,i)=><Pill key={x} active={i===0}><Text style={st.filterText}>{x}</Text></Pill>)}</ScrollView>{loading?<ActivityIndicator color={ZENO.colors.blue} style={{marginTop:35}}/>:items.length===0?<View style={st.empty}><Text style={st.quickIcon}>◌</Text><Text style={st.quickTitle}>لسه مفيش محادثات</Text><Text style={st.quickSub}>اكتشف شخص جديد وابدأ أول Chat.</Text><GradientButton title="اكتشف الآن" onPress={()=>go('discover')} small/></View>:<FlatList data={items} keyExtractor={x=>x.id} contentContainerStyle={st.list} renderItem={({item})=><GlassCard onPress={()=>open(item)} style={st.chatCard}><Avatar label={item.profile?.display_name||item.profile?.username||'User'} size={54}/><View style={st.chatBody}><View style={u.row}><Text style={st.chatName}>{item.profile?.display_name||item.profile?.username||'User'}</Text><Text style={st.time}>{item.last?.created_at?new Date(item.last.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'}):''}</Text></View><View style={u.row}><Text numberOfLines={1} style={st.chatMsg}>{item.last?.body||'ابدأ المحادثة الآن ✨'}</Text>{item.unread>0&&<View style={st.unread}><Text style={st.unreadText}>{item.unread}</Text></View>}</View></View></GlassCard>}/>}</View>
}

function Reels({go}:{go:(s:Screen)=>void}){return <View style={st.flex}><View style={st.header}><View><Text style={st.h1}>Reels</Text><Text style={st.muted}>اكتشف المحتوى اللي يشبهك</Text></View><IconButton icon="＋" onPress={()=>go('create')}/></View><ScrollView contentContainerStyle={st.reelsPage} showsVerticalScrollIndicator={false}>{reels.concat([{title:'Create with ZENO',user:'@zeno',views:'∞',tag:'CREATE',emoji:'✦'}]).map((r,i)=><Pressable key={r.title} style={st.reelFull} onPress={()=>i===3?go('create'):Alert.alert(r.title,'مشغل الـReel سيتم ربطه بالـmedia pipeline لاحقاً.')}><LinearGradient colors={i===3?['#0B1024','#312E81']:['#0F172A','#581C87']} style={st.fullArt}><Text style={st.fullEmoji}>{r.emoji}</Text><View style={st.fullShade}/><View style={st.fullInfo}><Pill active><Text style={st.tiny}>{r.tag}</Text></Pill><Text style={st.fullTitle}>{r.title}</Text><Text style={st.fullMeta}>{r.user} · {r.views} مشاهدة</Text></View><View style={st.reelActions}><Text style={st.actionBig}>♡</Text><Text style={st.actionBig}>💬</Text><Text style={st.actionBig}>↗</Text></View></LinearGradient></Pressable>)}</ScrollView></View>}

function Create({go}:{go:(s:Screen)=>void}){const items=[['🔴','Start Live','ابدأ بث مباشر وقرّب جمهورك','live'],['🎬','Upload Reel','فيديو قصير يوصلك بأكبر عدد','reels'],['✍️','Create Post','شارك فكرة، صورة أو تحديث','home'],['✦','Create with AI','حوّل فكرتك لمحتوى بمساعدة ZENO AI','ai']];return <ScrollView contentContainerStyle={st.page}><View style={u.row}><View><Text style={st.h1}>＋ ZENO</Text><Text style={st.muted}>مساحتك لصناعة أي حاجة</Text></View><IconButton icon="×" onPress={()=>go('home')}/></View><LinearGradient colors={['#151C45','#30145B']} style={st.createHero}><Text style={st.createKicker}>CREATE MODE</Text><Text style={st.createTitle}>فكرتك تبدأ من هنا.</Text><Text style={st.createSub}>اختار نوع المحتوى، وخلّي ZENO يكمل معاك.</Text></LinearGradient>{items.map(x=><GlassCard key={x[1]} onPress={()=>go(x[3] as Screen)} style={st.createCard}><Text style={st.createIcon}>{x[0]}</Text><View style={{flex:1}}><Text style={st.chatName}>{x[1]}</Text><Text style={st.chatMsg}>{x[2]}</Text></View><Text style={st.arrow}>›</Text></GlassCard>)}</ScrollView>}

function Notifications(){const [items,setItems]=useState<any[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{let active=true;supabase.from('notifications').select('*').order('created_at',{ascending:false}).limit(50).then(({data})=>{if(active)setItems(data||[]);setLoading(false)});let stop=()=>{};supabase.auth.getUser().then(({data})=>{if(data.user){stop=subscribeToMyNotifications(data.user.id,(payload)=>{if(payload.eventType==='INSERT')setItems(prev=>[payload.new,...prev].slice(0,50));else if(payload.eventType==='UPDATE')setItems(prev=>prev.map(x=>x.id===payload.new.id?payload.new:x));});}});return()=>{active=false;stop()};},[]);const icon=(type:string)=>({message:'💬',follow:'👤',follow_back:'👥',call:'📞',live:'🔴',gift:'🎁',luck:'🎉',game:'🎮',system:'✦'} as any)[type]||'🔔';const readAll=async()=>{await supabase.rpc('mark_all_notifications_read');setItems(prev=>prev.map(x=>({...x,read_at:new Date().toISOString()})))};return <ScrollView contentContainerStyle={st.page}><View style={u.row}><View><Text style={st.h1}>Notifications</Text><Text style={st.muted}>تحديثاتك لحظة بلحظة</Text></View><Pressable onPress={readAll}><Text style={st.action}>قراءة الكل</Text></Pressable></View>{loading?<ActivityIndicator color={ZENO.colors.blue} style={{marginTop:30}}/>:items.length===0?<GlassCard style={{marginTop:14}}><Text style={st.quickTitle}>مفيش إشعارات جديدة ✨</Text><Text style={st.quickSub}>هنبلغك هنا أول ما يحصل جديد.</Text></GlassCard>:items.map(n=><GlassCard key={n.id} style={st.notifCard}><View style={st.notifIcon}><Text style={{fontSize:22}}>{icon(n.type)}</Text></View><View style={{flex:1}}><Text style={st.chatName}>{n.title}</Text><Text style={st.chatMsg}>{n.body||''}</Text></View>{!n.read_at&&<View style={st.dot}/>}</GlassCard>)}</ScrollView>}

function Wallet({go}:{go:(s:Screen)=>void}){
  const [balance,setBalance]=useState(0); const [packs,setPacks]=useState<any[]>([]); const [tx,setTx]=useState<any[]>([]); const [loading,setLoading]=useState(true);
  useEffect(()=>{(async()=>{const [b,p,t]=await Promise.all([zeno.wallet.balance(),zeno.wallet.packages(),zeno.wallet.transactions(12)]);setBalance(Number(b.data?.balance||0));setPacks(p.data||[]);setTx(t.data||[]);setLoading(false)})()},[]);
  const money=(minor:number,currency:string)=>{const amount=minor/100;return `${amount.toFixed(amount%1?2:0)} ${currency}`};
  return <ScrollView contentContainerStyle={st.page}><View style={u.row}><View><Text style={st.h1}>Wallet</Text><Text style={st.muted}>الرصيد الحقيقي من حسابك</Text></View><IconButton icon="↗" onPress={()=>go('settings')}/></View><LinearGradient colors={gradients.primary} style={st.wallet}><Text style={st.walletLabel}>الرصيد الحالي</Text><Text style={st.walletCoins}>{loading?'…':balance.toLocaleString('en-US')}</Text><Text style={st.walletUnit}>ZENO COINS</Text><View style={st.walletLine}/><View style={u.row}><Text style={st.walletFoot}>الرصيد محفوظ Server-side</Text><Text style={st.walletSpark}>✦</Text></View></LinearGradient><SectionTitle title="اختار باقتك" action=""/><View style={st.packGrid}>{loading?[1,2,3,4].map(i=><GlassCard key={i} style={st.pack}><ActivityIndicator color={ZENO.colors.blue}/></GlassCard>):packs.map((p:any,i)=><GlassCard key={p.id} onPress={()=>Alert.alert('Coin Package',`${Number(p.coins).toLocaleString()} Coins · ${money(Number(p.price_minor),p.currency)}
الدفع الحقيقي يُنفّذ لاحقاً عبر مزود Payments.`)} style={st.pack}><View style={u.row}><Text style={st.packBadge}>{i===1?'POPULAR':i===2?'BEST VALUE':'ZENO'}</Text><Text style={st.packCoin}>◈</Text></View><Text style={st.packCoins}>{Number(p.coins).toLocaleString()} Coins</Text><Text style={st.packPrice}>{money(Number(p.price_minor),p.currency)}</Text></GlassCard>)}</View><GlassCard style={st.balanceInfo}><Text style={st.chatName}>💎 آخر العمليات</Text>{tx.length===0?<Text style={st.chatMsg}>لا توجد عمليات حتى الآن.</Text>:tx.slice(0,5).map((x:any)=><View key={x.id} style={[u.row,{marginTop:10}]}><Text style={st.chatMsg}>{x.type}</Text><Text style={x.amount>=0?st.packPrice:st.time}>{x.amount>0?'+':''}{x.amount} Coins</Text></View>)}</GlassCard></ScrollView>
}

function Profile({go,profile}:{go:(s:Screen)=>void;profile:any}){const name=profile?.display_name||'ZENO User', username=profile?.username||'setup';return <ScrollView contentContainerStyle={st.page}><LinearGradient colors={['#111A3D','#20113B']} style={st.profileHero}><Avatar label={name} size={96}/><Text style={st.profileName}>{name}</Text><Text style={st.handle}>@{username}</Text><Text style={st.bio}>{profile?.bio||'أهلاً بك في ZENO • More Than Just Chat.'}</Text><View style={st.stats}><View><Text style={st.statN}>0</Text><Text style={st.statL}>Following</Text></View><View><Text style={st.statN}>0</Text><Text style={st.statL}>Followers</Text></View><View><Text style={st.statN}>0</Text><Text style={st.statL}>Reels</Text></View></View><View style={u.row}><GradientButton title="تعديل الملف" onPress={()=>go('settings')} small/><GradientButton title="Wallet" onPress={()=>go('wallet')} small/></View></LinearGradient><SectionTitle title="مساحتي" action=""/><View style={st.profileGrid}>{[['🎬','Reels'],['❤️','Liked'],['🎁','Gifts'],['🏆','Badges']].map(x=><GlassCard key={x[1]}><Text style={st.quickIcon}>{x[0]}</Text><Text style={st.quickTitle}>{x[1]}</Text></GlassCard>)}</View><GlassCard onPress={()=>go('settings')}><Text style={st.chatName}>⚙️ الإعدادات والأمان</Text><Text style={st.chatMsg}>الحساب · الخصوصية · الجلسات · ZENO SAFE</Text></GlassCard></ScrollView>}

function Discover(){
  const [query,setQuery]=useState(''); const [people,setPeople]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [following,setFollowing]=useState<Record<string,boolean>>({});
  const load=async(q='')=>{setLoading(true);const {data,error}=await zeno.profile.discover(q,30);if(error)Alert.alert('Discover',error.message);setPeople(data||[]);setLoading(false)};
  useEffect(()=>{load()},[]); useEffect(()=>{const t=setTimeout(()=>load(query.trim()),350);return()=>clearTimeout(t)},[query]);
  const follow=async(id:string)=>{const is=!!following[id];const r=is?await zeno.profile.unfollow(id):await zeno.profile.follow(id);if(r.error){Alert.alert('Discover',r.error.message);return}setFollowing(v=>({...v,[id]:!is}))};
  return <ScrollView contentContainerStyle={st.page}><Text style={st.h1}>Discover</Text><Text style={st.muted}>أشخاص حقيقيين من مجتمع ZENO</Text><View style={st.searchWide}><Text style={st.searchIcon}>⌕</Text><TextInput value={query} onChangeText={setQuery} placeholder="ابحث باسم أو Username" placeholderTextColor={ZENO.colors.muted} style={st.searchInput}/></View>{loading?<ActivityIndicator color={ZENO.colors.blue} style={{marginTop:25}}/>:<View style={st.discoverGrid}>{people.map((x:any)=><GlassCard key={x.id} style={st.person}><Avatar label={x.display_name||x.username||'User'} size={62}/><Text style={st.chatName}>{x.display_name||x.username||'User'}</Text><Text style={st.chatMsg}>@{x.username||'zeno'} {x.is_verified?'✓':''}</Text><Pressable onPress={()=>follow(x.id)}><Pill active={!!following[x.id]}><Text style={st.filterText}>{following[x.id]?'متابَع':'متابعة'}</Text></Pill></Pressable><GradientButton title="Message" onPress={async()=>{const r=await zeno.chat.createDirect(x.id);if(r.error){Alert.alert('Chat',r.error.message);return}Alert.alert('Chat','تم إنشاء المحادثة. افتح Chats لبدء الرسائل.')}} small/></GlassCard>)}</View>}</ScrollView>
}

function AI(){const [text,setText]=useState('');const [msgs,setMsgs]=useState([{r:'a',t:'أهلاً! أنا ZENO AI ✦\nقولّي عايز تعمل إيه وأنا أساعدك.'}]);return <KeyboardAvoidingView style={st.flex} behavior={Platform.OS==='ios'?'padding':undefined}><View style={st.header}><View><Text style={st.h1}>ZENO AI ✦</Text><Text style={st.muted}>Your creative copilot</Text></View></View><ScrollView contentContainerStyle={st.page}>{msgs.map((m,i)=><View key={i} style={[st.aiMsg,m.r==='u'?st.aiUser:st.aiBot]}><Text style={st.aiText}>{m.t}</Text></View>)}</ScrollView><View style={st.composer}><TextInput value={text} onChangeText={setText} placeholder="اكتب رسالتك..." placeholderTextColor={ZENO.colors.muted} style={st.input}/><Pressable onPress={()=>{if(text.trim()){setMsgs(v=>[...v,{r:'u',t:text.trim()}]);setText('')}}} style={st.send}><Text style={{color:'#fff',fontSize:19}}>➤</Text></Pressable></View></KeyboardAvoidingView>}

function Live({go}:{go:(s:Screen)=>void}){
  const [streams,setStreams]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState(false);
  const load=async()=>{const {data,error}=await supabase.from('live_streams').select('id,host_id,title,status,started_at,created_at').eq('status','live').order('started_at',{ascending:false}).limit(20);if(error)Alert.alert('Live',error.message);setStreams(data||[]);setLoading(false)};
  useEffect(()=>{load()},[]);
  const start=async()=>{setBusy(true);const r=await zeno.live.start('ZENO Live ✦');setBusy(false);if(r.error){Alert.alert('Live',r.error.message);return}Alert.alert('LIVE','تم فتح بث مباشر في السيرفر. إضافة مزود البث المرئي WebRTC/streaming تأتي في طبقة الوسائط.');load()};
  const join=async(id:string)=>{const r=await zeno.live.join(id);if(r.error)Alert.alert('Live',r.error.message);else Alert.alert('انضممت ✦','أنت الآن داخل البث. طبقة الفيديو الحية ستُوصل بمزود الـRTC.');};
  return <View style={st.flex}><LinearGradient colors={['#070914','#201047']} style={st.liveScreen}><View style={u.row}><View><Text style={st.h1}>Live</Text><Text style={st.muted}>بثوث ZENO الحية</Text></View><View style={u.row}><GradientButton title={busy?'...':'Start Live'} onPress={start} small/><IconButton icon="×" onPress={()=>go('home')}/></View></View>{loading?<ActivityIndicator color={ZENO.colors.blue} style={{marginTop:30}}/>:streams.length===0?<View style={st.liveCenter}><Text style={st.quickIcon}>🔴</Text><Text style={st.liveTitle}>مفيش بث مباشر حالياً</Text><Text style={st.muted}>ابدأ أول Live من ZENO.</Text><GradientButton title="ابدأ Live" onPress={start} small/></View>:<ScrollView contentContainerStyle={st.page}>{streams.map((stream:any)=><GlassCard key={stream.id} onPress={()=>join(stream.id)} style={st.chatCard}><View style={st.liveRing}><Avatar label="ZENO" size={58} online/></View><View style={st.chatBody}><Text style={st.chatName}>{stream.title||'ZENO Live'}</Text><Text style={st.chatMsg}>● LIVE · اضغط للانضمام</Text></View><Pill active><Text style={st.filterText}>Join ›</Text></Pill></GlassCard>)}</ScrollView>}</LinearGradient></View>
}
function Games(){
  const [games,setGames]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState<string|null>(null);
  useEffect(()=>{zeno.games.catalog().then(({data,error})=>{if(error)Alert.alert('Games',error.message);setGames(data||[]);setLoading(false)})},[]);
  const play=async(slug:string)=>{setBusy(slug);const r=await zeno.games.createRoom(slug);setBusy(null);if(r.error){Alert.alert('Games',r.error.message);return}Alert.alert('Game Room','تم إنشاء غرفة لعب حقيقية 🎮\nRoom ID: '+r.data);};
  return <ScrollView contentContainerStyle={st.page}><Text style={st.h1}>Games</Text><Text style={st.muted}>العب، اجمع XP، ونافس أصحابك — بدون مراهنات.</Text>{loading?<ActivityIndicator color={ZENO.colors.blue} style={{marginTop:25}}/>:games.map((g:any)=><GlassCard key={g.slug} onPress={()=>play(g.slug)} style={st.game}><Text style={st.gameIcon}>{g.config?.icon||'🎮'}</Text><View style={{flex:1}}><Text style={st.chatName}>{g.name}</Text><Text style={st.chatMsg}>{g.description||'Play · Earn XP · Rematch'}</Text></View><Pill><Text style={st.filterText}>{busy===g.slug?'…':'Play ›'}</Text></Pill></GlassCard>)}</ScrollView>
}

function Settings({profile,onSaved}:{profile:any;onSaved:(p:any)=>void}){const [username,setUsername]=useState(profile?.username||'');const [name,setName]=useState(profile?.display_name||'');const [bio,setBio]=useState(profile?.bio||'');const save=async()=>{const u=username.trim().toLowerCase();if(!/^[a-z0-9_]{3,20}$/.test(u)){Alert.alert('Username غير صحيح','استخدم 3–20 حرفاً من a-z أو 0-9 أو _.');return}const {error}=await supabase.rpc('update_my_profile',{p_username:u,p_display_name:name.trim()||null,p_avatar_url:null,p_bio:bio.trim()||null,p_is_private:!!profile?.is_private});if(error){Alert.alert('تعذر الحفظ',error.message);return}onSaved({...profile,username:u,display_name:name.trim()||null,bio:bio.trim()||null});Alert.alert('تم','تم تحديث الملف بنجاح.');};return <ScrollView contentContainerStyle={st.page}><Text style={st.h1}>Settings</Text><Text style={st.muted}>تحكم في حسابك وخصوصيتك</Text>{[['Username',username,setUsername,'istring'],['Display name',name,setName,'string'],['Bio',bio,setBio,'string']].map(x=><View key={x[0] as string}><Text style={st.label}>{x[0] as string}</Text><TextInput value={x[1] as string} onChangeText={x[2] as any} placeholderTextColor={ZENO.colors.muted} style={st.inputBox}/></View>)}<GradientButton title="حفظ التغييرات" onPress={save}/><GlassCard style={{marginTop:14}}><Text style={st.chatName}>🛡 ZENO SAFE</Text><Text style={st.chatMsg}>الحظر · الإبلاغ · الجلسات · حماية الحساب</Text></GlassCard></ScrollView>}

function CinematicBoot(){const pulse=React.useRef(new Animated.Value(.55)).current;const scale=React.useRef(new Animated.Value(.88)).current;const line=React.useRef(new Animated.Value(0)).current;useEffect(()=>{Animated.parallel([Animated.loop(Animated.sequence([Animated.timing(pulse,{toValue:1,duration:1200,easing:Easing.inOut(Easing.ease),useNativeDriver:true}),Animated.timing(pulse,{toValue:.55,duration:1200,easing:Easing.inOut(Easing.ease),useNativeDriver:true})])),Animated.timing(scale,{toValue:1,duration:1100,easing:Easing.out(Easing.back(1.3)),useNativeDriver:true}),Animated.timing(line,{toValue:1,duration:1300,delay:350,easing:Easing.out(Easing.cubic),useNativeDriver:false})]).start()},[]);return <LinearGradient colors={['#03040B','#0B1026','#180C2D']} style={st.boot}><Animated.View style={[st.bootGlow,{opacity:pulse,transform:[{scale:pulse}]}]}/><Animated.View style={{transform:[{scale}]}}><Text style={st.bootLogo}>ZENO</Text><Text style={st.bootTag}>MORE THAN JUST CHAT.</Text></Animated.View><View style={st.bootLineTrack}><Animated.View style={[st.bootLine,{width:line.interpolate({inputRange:[0,1],outputRange:['0%','100%']})}]}/></View><Text style={st.bootKicker}>CONNECT · CREATE · EXPERIENCE</Text></LinearGradient>}

function Auth(){const [phone,setPhone]=useState('');const [code,setCode]=useState('');const [sent,setSent]=useState(false);const [busy,setBusy]=useState(false);const glow=React.useRef(new Animated.Value(.7)).current;useEffect(()=>{Animated.loop(Animated.sequence([Animated.timing(glow,{toValue:1,duration:1400,useNativeDriver:true}),Animated.timing(glow,{toValue:.65,duration:1400,useNativeDriver:true})])).start()},[]);const send=async()=>{const p=phone.replace(/\s+/g,'');if(!/^\+?[1-9]\d{7,14}$/.test(p)){Alert.alert('رقم الهاتف','اكتب رقم هاتف دولي صحيح مثل +201XXXXXXXXX');return}setBusy(true);const {error}=await supabase.auth.signInWithOtp({phone:p});setBusy(false);if(error){Alert.alert('تعذر إرسال الكود',error.message);return}setSent(true)};const verify=async()=>{if(code.trim().length<4)return;setBusy(true);const {error}=await supabase.auth.verifyOtp({phone:phone.replace(/\s+/g,''),token:code.trim(),type:'sms'});setBusy(false);if(error)Alert.alert('الكود غير صحيح',error.message)};return <LinearGradient colors={['#03040B','#0C1027','#190B31']} style={st.auth}><Animated.View style={[st.authGlow,{opacity:glow}]}/><View style={st.authBrand}><Text style={st.authLogo}>ZENO</Text><Text style={st.authTag}>MORE THAN JUST CHAT.</Text></View><Text style={st.authTitle}>{sent?'كود الدخول وصل ✦':'أهلاً بك في عالم ZENO'}</Text><Text style={st.authSub}>{sent?'اكتب الكود المرسل إلى رقمك للمتابعة.':'التسجيل إجباري للانضمام إلى ZENO وحماية حسابك.'}</Text><View style={st.authCard}><Text style={st.authLabel}>{sent?'رمز التحقق':'رقم الهاتف'}</Text><TextInput value={sent?code:phone} onChangeText={sent?setCode:setPhone} keyboardType={sent?'number-pad':'phone-pad'} placeholder={sent?'••••••':'+20 1XXXXXXXXX'} placeholderTextColor={ZENO.colors.muted} style={st.authInput}/><GradientButton title={busy?'جاري التأمين...':sent?'دخول ZENO':'ابدأ الآن'} onPress={sent?verify:send}/>{sent&&<Pressable onPress={()=>{setSent(false);setCode('')}}><Text style={st.authBack}>تغيير رقم الهاتف</Text></Pressable>}</View><Text style={st.legal}>بالمتابعة أنت توافق على شروط ZENO وسياسات الخصوصية والأمان.</Text></LinearGradient>}

function Onboarding({onDone}:{onDone:(p:any)=>void}){const [username,setUsername]=useState('');const [name,setName]=useState('');const [bio,setBio]=useState('');const save=async()=>{const u=username.trim().toLowerCase();if(!/^[a-z0-9_]{3,20}$/.test(u)){Alert.alert('Username','استخدم 3–20 حرفاً من a-z أو 0-9 أو _.');return}const {error}=await supabase.rpc('update_my_profile',{p_username:u,p_display_name:name.trim()||null,p_avatar_url:null,p_bio:bio.trim()||null,p_is_private:false});if(error){Alert.alert('تعذر إنشاء الحساب',error.message);return}const id=(await supabase.auth.getUser()).data.user?.id;const {data}=await supabase.from('profiles').select('id,username,display_name,avatar_url,bio,is_private,is_verified').eq('id',id||'').maybeSingle();onDone(data||{username:u,display_name:name,bio,is_private:false})};return <LinearGradient colors={['#070914','#15103A']} style={st.auth}><Logo/><Text style={st.authTitle}>خلينا نجهز حسابك ✨</Text><Text style={st.muted}>بيانات ظهورك على ZENO وتقدر تعدلها بعدين.</Text><TextInput value={username} onChangeText={setUsername} autoCapitalize="none" placeholder="Username" placeholderTextColor={ZENO.colors.muted} style={st.authInput}/><TextInput value={name} onChangeText={setName} placeholder="الاسم الظاهر" placeholderTextColor={ZENO.colors.muted} style={st.authInput}/><TextInput value={bio} onChangeText={setBio} placeholder="نبذة قصيرة (اختياري)" placeholderTextColor={ZENO.colors.muted} style={st.authInput}/><GradientButton title="دخول ZENO" onPress={save}/></LinearGradient>}
function Nav({screen,go}:{screen:Screen;go:(s:Screen)=>void}){return <View style={st.nav}>{[['home','⌂','Home'],['chats','◌','Chats'],['create','＋',''],['reels','▶','Reels'],['profile','◎','Profile']].map(x=><Pressable key={x[0]} onPress={()=>go(x[0] as Screen)} style={x[0]==='create'?st.center:st.navItem}><Text style={x[0]==='create'?st.centerIcon:st.navIcon}>{x[1]}</Text>{x[2]?<Text style={[st.navLabel,screen===x[0]&&st.active]}>{x[2]}</Text>:null}</Pressable>)}</View>}

export default function App(){const [screen,setScreen]=useState<Screen>('home');const [session,setSession]=useState<any>(null);const [profile,setProfile]=useState<any>(null);const [loading,setLoading]=useState(true);const [boot,setBoot]=useState(true);const [activeCall,setActiveCall]=useState<ActiveCall|null>(null);const loadProfile=async(id:string)=>{const {data}=await supabase.from('profiles').select('id,username,display_name,avatar_url,bio,is_private,is_verified').eq('id',id).maybeSingle();setProfile(data)};useEffect(()=>{const timer=setTimeout(()=>setBoot(false),2800);supabase.auth.getSession().then(async({data})=>{setSession(data.session);if(data.session)await loadProfile(data.session.user.id);setLoading(false)});const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>{setSession(s);if(s)setTimeout(()=>loadProfile(s.user.id),0);else setProfile(null)});return()=>{clearTimeout(timer);subscription.unsubscribe()}},[]);if(boot)return <CinematicBoot/>;if(loading)return <SafeAreaView style={st.root}><ActivityIndicator size="large" color={ZENO.colors.blue}/></SafeAreaView>;if(!session)return <SafeAreaProvider><SafeAreaView style={st.root}><Auth/></SafeAreaView></SafeAreaProvider>;if(!profile)return <SafeAreaProvider><SafeAreaView style={st.root}><Onboarding onDone={setProfile}/></SafeAreaView></SafeAreaProvider>;const go=(s:Screen)=>setScreen(s);let body:any;switch(screen){case'home':body=<Home go={go}/>;break;case'chats':body=<Chats go={go} onStartCall={setActiveCall}/>;break;case'create':body=<Create go={go}/>;break;case'reels':body=<Reels go={go}/>;break;case'profile':body=<Profile go={go} profile={profile}/>;break;case'discover':body=<Discover/>;break;case'wallet':body=<Wallet go={go}/>;break;case'notifications':body=<Notifications/>;break;case'ai':body=<AI/>;break;case'live':body=<Live go={go}/>;break;case'games':body=<Games/>;break;default:body=<Settings profile={profile} onSaved={setProfile}/>;}return <SafeAreaProvider><SafeAreaView style={st.root}><View style={st.flex}>{body}</View>{screen!=='live'&&<Nav screen={screen} go={go}/>}<CallManager externalActive={activeCall} onActiveChange={setActiveCall}/></SafeAreaView></SafeAreaProvider>}

